quests[82629] = { id = 82629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerub-ar Palace: For Nerubian Eyes Only", description = "Our tunnels were not built for your kind... too difficult and treacherous to navigate alone. \n\nFetch me signets from The Silken Court, Scarab Lord Anub'arash and Skeinspinner Takazj, and I will grant you hidden passage to the palace.", progress = "Safe passage has its price.", completion = "Do not stray into the shadows, {name}--I cannot guarantee your safety.", objectives = "Collect 3 Signets of the Thousand Scars and 3 Signets of the Skeinspiner within Nerub-ar Palace on Normal difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
