quests[82650] = { id = 82650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Pinch of Salt" }
quests[82651] = { id = 82651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omens Unified", description = "By the titans! Observe this item, {class}.\n\n<Custodian Khubon shows you something resembling a fractured gem.>\n\nThis is a fractured spark of omens. In the hands of a skilled crafter, a reagent such as this can be infused into other materials to vastly improve the final product.\n\nHowever, this is merely a fragment. If you chance upon another in your adventures, bring it to me. I will combine this one with yours and grant you a complete spark of your own.", progress = "Ah, {name}. What is the progress of your search for another fractured spark of omens?", completion = "Excellent. If you acquire more fractured sparks, you can combine them yourself for use in your own crafting efforts.", objectives = "Find another Fractured Spark of Omens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82653] = { id = 82653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggregation of Horrors" }
quests[82658] = { id = 82658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drop and Go" }
quests[82659] = { id = 82659, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worldsoul: Nerub-ar Palace", description = "Queen Ansurek has proven herself both cruel and cunning. We cannot allow her forces to continue to grow in strength with Xal'atath's black blood. \n\nIt has come to this. A daunting task indeed. With the greatest of our forces, we shall lay siege to Nerub-ar Palace!You will learn:", objectives = "Complete the Nerub-ar Palace raid on Normal difficulty or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82672] = { id = 82672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Another Timely Invitation", description = "The bronze dragonflight is throwing a celebration just outside the Caverns of Time in Tanaris!\n\nThere are all sorts of new activities to partake in that honor and remember what has transpired over the years.\n\nHead to Tanaris and join in the festivities.", completion = "Welcome! \n\nIt's that special time of year when the bronze dragonflight celebrates all that has happened over the years.\n\nYou, {name}, are a most honored guest!", objectives = "Visit the celebration in Tanaris outside the Caverns of Time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82676] = { id = 82676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broken Masquerade", description = "I cannot remember how I arrived at this swamp, but it was great luck that I did. As I wandered, I spotted Lady Katrana Prestor entering a strange toothy cave. Now, what would a noblewoman be doing in such a ghoulish place?\n\nFollowing her closely, I found a great clutch of black dragon eggs within the lair. Such evidence is clear. Katrana is Lady Onyxia! \n\nI beg of you, aid me in defeating this vile dragon once and for all.", progress = "If only Varian were here. Surely he'd have no issue slaying her.", completion = "Is it true? She finally rests?\n\nHers was an unwavering ambition. It's good that we stopped her when we did. I cannot imagine the tragedies that would have followed if she was allowed to continue her ploys and schemes.", objectives = "Defeat Remembered Onyxia during a Radiant Echoes event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82678] = { id = 82678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archives: The First Disc", description = "I am pleased to report progress has been made restoring the titan Vault of Memory in the Archive. I have the mainframe up and running--but part of its internal mechanism has failed over time.\n\nGetting parts for it will be a challenge, which is why we need your help. Come with me to the Vault of Memory. We can discuss what we need with Dagran.", progress = "Did you happen to find anything?", completion = "These are perfect! The corrosion levels on these parts are minimal. We should be able tae salvage whatever information they hold.\n\nLet's uncover some buried knowledge, {name}!", objectives = "Meet with Dagran in the Vault of Memory and assist him in finding titan disc fragments.\n\nThese disc fragments can be looted from dungeons, delves, and dangerous creatures and treasures across Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82679] = { id = 82679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archives: Seeking History", description = "We're still processing the data in the Archive and restoring what we can. But... the discs we've recovered so far in the Archive itself are unusable.\n\nFinding more of these discs are a priority. We must reclaim our memories.\n\nReturn what you find to Dagran. He is assisting me in rebuilding the Archive.", progress = "Have ye found anythin'?", completion = "More o' them! I wonder what we'll discover this time!", objectives = "Collect 100 titan disc fragments.\n\nThese disc fragments can be looted from dungeons, delves, and dangerous creatures and treasures across Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82680] = { id = 82680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Birdman of the Three Shields", description = "Are you here to watch the mosswools? No? \n\nThat's too bad. I find the elemental creatures on our isle fascinating. I'm not the only one. \n\nAn old friend of mine named Olbarig resides out on the Three Shields. He studies the wild cloudrooks there.\n\nBut come to think of it, I haven't heard from him in awhile. Maybe someone should check on him. Hm. Would you mind?", completion = "Harmot sent you to check on me? \n\nHuh. Well, I didn't know that sack of charcoal cared.\n\nBut he does have an innate sense of when elementals are in turmoil. Maybe he knew something was brewing out here.\n\nHarmot's timing is good, outlander. And your aid would be most welcome.", objectives = "Find Olbarig on the Three Shields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82681] = { id = 82681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloudrook Down", description = "You see that flock in the distance? Wild cloudrooks. \n\nThey've lived on these islands peacefully for ages. But recent events have stirred other elementals from the earth and sea. One of the cloudrooks was attacked, and it was... disincorporated.\n\nNow the flock circles endlessly. Surely they will tire soon. If they get too tired...\n\nPerhaps if we cleared the hostile elementals from this island, they will return and take their rest.", progress = "This is the cloudrooks' habitat. Your crash and our war with the nerubians is what caused the other elementals to come.\n\nWe should set this right.", completion = "Many thanks for your help, outlander. Though the cloudrooks do not seem any more inclined to return to land.\n\nIf this is some kind of mourning, I worry it could drive the rooks to exhaustion and their own disincorporation. \n\nWe must try something else.", objectives = "Cull the riled elementals from the central Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82682] = { id = 82682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Hors D'Oeuvres", description = "The cloudrooks cannot possibly circle forever, and I cannot bear more of them being lost. But maybe they'd roost if we tempted them with their favorite food?\n\nThe eels that swim in these waters carry a small electrical charge not unlike the mosswool favored by their faster, stronger cousins the stormrooks. I once reasoned that cloudrooks might enjoy the eels for similar reasons. \n\nAnd I confess... I've been feeding them the eels ever since. \n\nGather some up and give it a go.", progress = "The eels may not pack quite the punch of Rambleshire mosswool, but the cloudrooks seem to prefer it that way.", completion = "These should do.\n\nHope you didn't get any nasty shocks gathering them up.\n\nWe can restore some energy to the cloudrooks and show them that it's safe to land.", objectives = "Gather 10 Electric Eels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82689] = { id = 82689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only Darkness", description = "Long have I waited for this day, hero. Are you and your allies prepared to bring the Lich King to justice? We charge on your command!", progress = "We battle for the fate of Azeroth. For the light of dawn!", completion = "So, at last it is done.\n\nMay the people of Azeroth remember our deeds here forevermore. May the sacrifices of so many burn in their hearts eternally. May they never fail to risk mortal peril in the face of great evil.", objectives = "Defeat Remembered Lich King during a Radiant Echoes event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82690] = { id = 82690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lingering Shadows", description = "When we faced Xal'atath's forces in Hallowfall, I sensed something dark just beneath the surface. Something that was not her, but it still troubles me.\n\nI have learned that running into every situation myself is not always the best tactic. Sometimes, a leader must stand back to see the field.\n\nSo, I send you.\n\nGo to Hallowfall, and uncover what you can about this mysterious force. I don't want to be caught blind again.", completion = "I didn't expect to see you here.\n\nBut then, you always manage to show up where there's something interesting, don't you? \n\nThere is no time for talk, though. My people have run into problems.", objectives = "Return to where Alleria sensed Black Blood in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82691] = { id = 82691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Breathing Room", description = "We all followed Orweyna to these surface caves because we believed in what we were doing. But this... We did not bargain for so many injuries, so much dogged searching.\n\nFor now, we just need a little breathing room. Slay the creatures out there that are harming us, and we can get the space to address the real issue.", progress = "Our people are fierce and strong. We are accustomed to being outnumbered. But this is too much.", completion = "That should give us some space to retreat.\n\nAnd now we must deal with the crux of the issue. That is, Orweyna's ever-lasting determination to pursue this mission, no matter the cost.\n\nIt's time we had a talk.", objectives = "Slay Seeping creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82692] = { id = 82692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Price of a Mission", description = "I don't know what prompted you to come here, but we could use your help. \n\nWe came to investigate signs of the Black Blood in this area, but the creatures overwhelmed us. Several of us are still out in the field.\n\nYou are hale and hearty. Go find my people so they can return.\n\nAnd, if you have the strength, take a closer look at the strange flowers that grow from the blood that seeps beneath the ground. They may hold a clue as to how we can fight against its corruption.", progress = "Have you found my people?", completion = "<Orweyna counts the number of haranir silently-- to reassure herself. Then she nods.>\n\nThat's all of us. And I'm grateful. \n\nThose flowers you found are also odd. They seem to have corrupted properties and have become something new. I have to dig into this more.\n\nWe can't stop now. Not when we're so close. This could be the key to how we fight back.", objectives = "Find the pinned-down haranir and examine Strange Flowers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82693] = { id = 82693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing in the Way", description = "Some of these creatures are stronger than others. When we were able to act together and fresh to the fight, these creatures were no threat. Now our injuries and separation leave us vulnerable. \n\nMy people are resilient, but we are not immortal.\n\nThere is one beast larger than all the others. That beast is making it difficult for the haranir to return and recover.\n\nSlay it, so they can be safe.", progress = "Once we are together again I know we will be able to regroup and continue.", completion = "<Orweyna nods.>\n\nThank you.", objectives = "Defeat the Bloodcrust Behemoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82694] = { id = 82694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Together, Alone", description = "I am not blind. I know that they are tired and weary. But we are so close to figuring out what we can do about the Black Blood.\n\nThe importance of what we uncover goes beyond Hallowfall, or the nerubian kingdom. There is so much more work if we are to find a solution.\n\nFor now, let us withdraw and recover. Somewhere away from these creatures.", completion = "Na'layro. Kai'shae. Ney'leia. On'hiea.\n\nHannan.\n\nWe were a family all on our own, here, far away from home. \n\nI do not blame them for wanting to return, but I would blame myself if I gave up now. I must focus on what comes next.", objectives = "Meet Hannan in Hallowfall to hear the plan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82695] = { id = 82695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice", description = "Here is where I must focus. I can hear the voice of my goddess, and she must be near.\n\nI will enter a meditation to ask what I must do. How can I continue this mission alone? How can I go on without the others?\n\nStay close. I don't know what may lurk or threaten while I am concentrating.", progress = "<Orweyna is unresponsive as she focuses entirely on her meditation.>", completion = "I understand.\n\nWe must go to where I can hear the sounds of things moving beneath the stones. I don't know what it means, I only know that I must go there.\n\nWill you go with me?", objectives = "Defend Orweyna as she meditates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82696] = { id = 82696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ringing in the Deeps", description = "My vision was clear to me. I need to continue this work.\n\nI need to find out how we can stop the Black Blood from spreading, before it's too late for your people, and for mine.\n\nMeet me in the Ringing Deeps. I will be in a form that allows me to hide and to listen without anyone noticing.", completion = "There seem to be goblins everywhere now. \n\nDo not look too closely at me, or you will draw attention. We need to get closer to where the goblins are working.", objectives = "Meet Orweyna at Camp Murroch in the Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82697] = { id = 82697, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Help These Days", description = "Seeing you here is a welcome surprise!\n\nThere's something big happening over at Opportunity Point, but it's hard to know what without getting closer to the people working there. \n\nI know Haxle's involved. We'll need his paperwork if we want to be able to ask around without trouble. \n\nHe's headed down to Opportunity Point. \n\nGo, follow him, and see if he's got anything on him we can use. Don't worry about the mess-- I know you're discreet when you need to be.\n\nAnd... also not, when you need to be.", progress = "Got that work order? We can open up way more doors with it than without it.", completion = "Perfect. Now anytime someone asks why we're here, we've got this. Now it's time to do a little snooping.\n\n... There are a lot more goblins here than I remember. Something's definitely going on.", objectives = "Find Haxle Drillbit and shake him down for access to the operation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82698] = { id = 82698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haywired and Hostile", description = "I saw many machines nearby, and all of them seem to make dreadful noises. I cannot hear the one that I heard in the vision, though, at least not clearly.\n\nDestroy the excess ones. They are only in the way.\n\nWhile you are quieting the scene, I will hunt and scout.", progress = "You're not who I expected to see here.", completion = "Looks like you're interested in the foreman's office too, huh?\n\nDon't get cranky, we're on the same side here. I just can't get close without being seen. \n\nAnd then there's just one big, clanking wrinkle to this whole mess.", objectives = "Destroy the haywire excavators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82699] = { id = 82699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hey, What's Going On?", description = "Time to do some networking. \n\nThere's a bunch of goblins outside of Opportunity Point, over there in the Abyssal Excavation. I heard some of them grumbling as they started their shift.\n\nLet's see what some friendly words shake loose.\n\nWhile you're out there, check out the used fuel drums. They wouldn't let me look inside the full drums, but they just drop the used ones around the work site.", progress = "We've got to stop meeting like this. Assuming we've met before, which, maybe we have.", completion = "Those goblins only know part of the story. What's in there is the full story, or at least, a big piece that's missing.", objectives = "Search for clues by questioning goblins and uncovering evidence in the Abyssal Excavation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82700] = { id = 82700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Built to Blast", description = "We've got an intel problem, but we've also got a clank problem.\n\nIf you look over there, there's a big, haywire mech that's just going crazy. There's no way anyone's going to uncover anything while that's out in the field.\n\nWe should do something about that.", completion = "It would seem that we are all searching for information, but I have some that I think is useful.\n\nAnd it's too late to hide now, they've seen my true form. \n\nLet's see this through to the end.", objectives = "Destroy the Haywire MEK IV.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82701] = { id = 82701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bat Versus World", description = "When I scouted, I heard and saw things that I don't understand. \n\nPerhaps if I describe it to you and the goblins, you will know what it means.", completion = "After I escaped from that place, I saw you battling the gigantic machine, and I had to join in the fight.\n\nNow it seems there really is no going back. I am alone here, except for you, and these goblins.", objectives = "Experience Orweyna's scouting mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82702] = { id = 82702, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Found Friends", description = "So Gallywix has chosen to show his ugly face here, and it looks like he's got himself organized.\n\nWe should report this to Alleria. See how she wants to handle it.", completion = "You've brought me far more than just information. \n\nAlthough I have a feeling that this... Orweyna... will not give up her secrets easily. I should be patient. I am sure that we will find common ground eventually.\n\nIn the meantime, there is someone that she should talk to.", objectives = "Report to Alleria in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82706] = { id = 82706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Worldwide Research", description = "It's been all quiet recently. I've nae heard of any issues. \n\nThis seems like a good opportunity for exploration, eh? I'm at yer disposal! We can go wherever it is ye want tae go!", progress = "Dangerous exploration? Survivin' by the skin of our teeth? Makes this ol' {race} feel alive!", completion = "Got tae see some nice places today. That's always good. Gets the ol' heart pumpin'.", objectives = "Complete 3 Delves in The War Within.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82707] = { id = 82707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Earthen Defense", description = "Just the person I was lookin' for!\n\nMerrix mentioned that the earthen have been havin' problems recently, and I thought tae myself, \"Brann, you know who likes solving problems? {name}!\"\n\nWant tae go put on yer delvin' hat?", progress = "Feels good tae be doing good work.", completion = "There is nae anythin' that can stand in the way of Brann and {name}!\n\nHmm, {name} and Brann? Not sure what way sounds best. I'll add it tae the tae do list.", objectives = "Complete 2 Delves in the Isle of Dorn or The Ringing Deeps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82708] = { id = 82708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Nerubian Menace", description = "{name}! Come in, come in!\n\nI've been talkin' tae everyone in Dornogal, and it seems like the nerubians have been kickin' up a fuss all over Khaz Algar. \n\nWhat's say you and I go put on our spider kickin' boots and give them somethin' tae really fuss about?", progress = "I better not get webs on my hat again. Took me weeks tae find all the strands from last time!", completion = "That'll teach those nerubians tae not be so feisty, eh?\n\nYou set them up, I knock them down! Or tae other way around. I'm not fussy.", objectives = "Complete 2 nerubian Delves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82709] = { id = 82709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Percussive Archaeology", description = "I've been investigatin' all of the interesting looking pieces we've found in our travels. Many of them are critical tae Azeroth's history! And those rotters in the delves are just smashin' them up without a care in the world!\n\nLet's put a stop tae it and recover what we can. I bet if we went up against one of the really tough crowds, they'd have loads of fragments for us.", progress = "I cannae believe that some folks don't care about history. Just makes me sad.", completion = "We may have just got fragments, {name}. But with fragments, ye can rebuild it. Ye can see what it once was.\n\nFragments are better than dust, is all I'm saying.", objectives = "Recover 30 Khaz Algar Archeological Fragments from Delves in Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82710] = { id = 82710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Empire-ical Exploration", description = "Champion of the hour, here tae see little ol' me!\n\nI've been talkin' to Faerin, and apparently the critters in the delves of Hallowfall have been actin' up. Or is it actin' down?\n\nDoes nae matter, does it? What's say we go and help them out, eh?", completion = "I just dinnae understand why anyone would attack the Arathi. Everyone there is trained tae be on the offensive! \n\nSeems like the daftest folks tae attack.", objectives = "Complete 2 Unique Delves in Hallowfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82711] = { id = 82711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Lost and Found", description = "I have a bit o' a personal request, {name}. I lost some of my tools on our adventures. My lucky letter opener, my compass...\n\nAnd ye may have already noticed, but I'm wearing a different hat. This one is a tatty ol' rag compared tae the glorious one I normally have on my head!\n\nCan we go investigate some of the delves and see where I left them?", progress = "Looking forward tae getting this ugly hat off my head!", completion = "Oh, my hat... I love ye, hat. \n\nAnd the other stuff too, I love them as well. Just not as much as my hat.", objectives = "Recover Brann's 3 lost belongings in Delves around Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82712] = { id = 82712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Trouble Up and Down Khaz Algar", description = "I'm hearin' there's trouble all over Khaz Algar right now. Delve critters are getting all feisty. \n\nWe should go handle it! Top tae bottom, show them that gettin' aggressive is not in their best interests!", completion = "That's a... remarkably literal interpretation of my earlier comments, {name}. \n\nBut still, we showed them the dangers of gettin' too aggressive--aggression right back at 'em!", objectives = "Complete a Delve in the Isle of Dorn and a Delve in Azj-Kahet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82739] = { id = 82739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82740] = { id = 82740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", objectives = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82746] = { id = 82746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delves: Breaking Tough to Loot Stuff", description = "I've been itchin', {name}. \n\nItchin' to teach the delve critters a lesson! We need tae hit them hard. Hit the tough ones, so the weak ones will nae even poke their heads out!\n\nWill ye join me?", completion = "Woo! We came, we saw, we kicked 'em in the face!\n\nKhaz Algar is safer now from the predations of evil critters. Good days work, eh?", objectives = "Complete two Delves of Tier 6 or above.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82747] = { id = 82747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossroads Plaza", description = "Hello, outlander. Do you want to know about news from outside the city?\n\nThe Crossroads is a key place for earthen to exchange information and goods, no matter their allegiances or edicts.\n\nMy friend Bondaz unofficially maintains the square. He would be delighted to see you in person. I'm sure he has already heard a hundred different stories of how you and the outlanders made it to our isle.", completion = "...An outlander? You are real! Just like the others that have stopped by. There are so many of you!\n\nI can't believe my eyes. I know everything about the isle, but could not have fathomed this.", objectives = "Meet Bondaz in Crossroads Plaza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82748] = { id = 82748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deephaul Ravine", description = "We've received reports of troubles in the earthen depths. Explore the Deephaul Ravine and the resources available, then report to Ruffious.", completion = "You made it through the mines! Splendid!", objectives = "Complete the Deephaul Ravine battleground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82762] = { id = 82762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping a Close Tabard", description = "Wow!\n\nThat's a super nifty tabard! And it's all yours to customize however you want.\n\nKessa should be able to help you bring your designs to life.\n\nGo ahead and pay her a visit to get started!", progress = "Kessa is a very skilled tabard designer!", completion = "I'd be happy to help you design your personal tabard!", objectives = "Speak with Kessa in the Victorious Visage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82768] = { id = 82768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloud Fishing", description = "Now that we have the eels, we can try to lure the cloudrooks back to land. \n\nHead over to the neighboring island. Get as close as you can and make an offering to the rooks. \n\nWith luck, they'll cease their circling and come down for a nourishing meal.", progress = "Nothing better than electric eels to sate a tired and hungry cloudrook.", completion = "Now I understand. This is how the rooks bring their own over from the elemental plane. They weren't mourning so much as calling out to their departed kin.\n\nThank you for your help, outlander. You've helped me better understand these beautiful creatures.", objectives = "Offer 7 Electric Eels to Wild Cloudrooks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82771] = { id = 82771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heritage of the Earthen", description = "The time has come to give back to the Archives. \n\nAll earthen wanderers are invited to share their experiences for the preservation of what has come before and the betterment of those who will come after. \n\nThis knowledge and experience of the wider world of Azeroth is a priceless treasure, and the practice of sharing it is key to our earthen heritage.", progress = "Have you uploaded your experiences yet?", completion = "We cannot thank you enough for this gift. Your experiences will be invaluable to the {race} still now awakening in the Ringing Deeps. Please accept this and wear it proudly as you continue to travel amongst the peoples of Azeroth and beyond.", objectives = "Upload experiences to the Archives in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82773] = { id = 82773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Functional Favor", description = "I am seeking my mentor, Foreman Arbauch. He is... missing. Under other circumstances, I would send for a search party from Gundargaz, but there is no time.\n\nI suspect he passed through here, but the only lead I have is DelGizmo. He wants the local fog beasts removed. Reluctance. But if he has seen Arbauch, I must learn what he knows.\n\nThe lurkers to the south carry powerful Galvanic Glands. They have enough charge to disperse even the thickest fog. Retrieve some. Compensation assured.", progress = "Haste is appreciated. I must find Arbauch.", completion = "Approval. These seem quite energetic. They will allow you to scare off the fog beasts for DelGizmo.", objectives = "Collect 6 Galvanic Glands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82774] = { id = 82774, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antifogmatic", description = "Machine speakers have no love for fog beasts. Where there is fog, rust is sure to follow. Still, I'd prefer not to harm them. Arbauch always said it was bad luck.\n\nTake this device. The glands you collected should provide enough power to disperse the fog without hurting the fog beasts within.\n\nCaution. Fog beasts are skittish, but other creatures may also lurk.", progress = "Is it done? We have little time to waste.", completion = "Fine work. I hope DelGizmo's information is worth the trouble.", objectives = "Disperse the fog around Camp Murroch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82775] = { id = 82775, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quickchange Artist", completion = "See, character is as much in the costume as it is you. \n\nPracticing getting in and out of costume fast is just as important as practicing lines.\n\nNow you can switch roles quickly and be a virtuoso of versatility!", objectives = "Receive tips from Wendeline in the Proscenium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82776] = { id = 82776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[82777] = { id = 82777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[82778] = { id = 82778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallowfall Fishing Derby", completion = "These are some great catches, {name}--I can't wait to see what you'll reel in next week!", objectives = "Catch these Trophy Fish before the Derby Dasher buff expires: Nibbling Minnow, Arathor Hammerfish, Queen's Lureback.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82781] = { id = 82781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attention-Getter", completion = "We must be careful with fans. We must be gentle with their feelings but also discourage unwanted behaviors.\n\nKind and gracious acknowledgement of their gratitude is key. A simple thank you note in return is optimal. And if you see them here, it is acceptable to nod and wave. We want our audience to be happy, of course.\n\nAnd, in the event they bring flowers... I can graciously take that burden from you.", objectives = "Receive tips from Elma in the Proscenium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82782] = { id = 82782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authenticity in Dress", completion = "Excellent. I cherish every barrier I can remove between an actor and their directive.\n\nTreat the costumes with care. We will be using them in future plays, remember.\n\nGood luck! And don't forget you're part of the troupe now!", objectives = "Speak with Rabaan in the Proscenium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82783] = { id = 82783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromie's Codex", description = "Hello there! I could really use your help. \n\nYou see, my codex has gotten a bit jumbled in all my travels lately, and I have to give a time tour back to the gates of Ahn'Qiraj in an hour. \n\nI need you to jump in with me to sort out any... inconsistencies. Then it should be right as rain and all the visitors here will have a fun, not-super-dangerous tour!", progress = "Whew, that was pretty dicey there for a moment. I thought you might not have made it!", completion = "Thanks so much for the help!\n\nI'm so excited for my first tour. It's MUCH more likely that no one will die or get lost now, thanks to you. Not that it has happened... ever...", objectives = "Complete the Codex of Chromie event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82784] = { id = 82784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resonant Performance", completion = "We decided that this was the least we could do to thank you for sharing your experience with us.\n\nI have much more to learn myself. So please, join us for another play.", objectives = "Speak with Burkhalt in the Proscenium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82785] = { id = 82785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghosts in the Machine", description = "There's a substation directly below us? Perhaps that is where Arbauch went to hide it... Disregard, we must investigate.\n\nWith luck, Arbauch may still be here. The entrance should be to the north, near the pool of water from the burst pipe. Please, come with me. He may need our help.\n\nI will explain everything once he is located.", completion = "It killed him, and we let it loose. Even his memory gem is gone.", objectives = "Find Foreman Arbauch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82786] = { id = 82786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duty of Care", description = "The golem is unstable. I doubt it can travel far. We will track it, but haste failed me once already. Arbauch showed true devotion to the machines--we will follow his example. Repairs must come first.\n\nMachine systems are delicate. We must activate the backup before the failure can cascade. Exterminate any pests you find as well. Even the smallest creature can ruin delicate machinery.\n\nI am damaged. I will send my cogwalker with you to relay instructions.", progress = "Our primary duty is to mend.", completion = "The backup systems are operational. Now we may track the golem.", objectives = "Activate the backup systems along the Cataract River.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82787] = { id = 82787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Rise of the Colossals", description = "WQ", objectives = "Kill Colossal beasts", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82792] = { id = 82792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Ore Nothing", description = "Outlander. Your aid is requested. \n\nThe earthen here have said you would be of help. \n\nOur fellow earthen at the Opalcreg have not reported their quota for the past day. There must be something causing a disruption.  \n\nWould you pay Foreman Alvegar a visit?", completion = "I'm hiding... lay low. \n\nForeman Germira sent you? She must be worried that we haven't sent over our quota.", objectives = "Go to the Opalcreg and seek out Alvegar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82796] = { id = 82796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Mine Blind", description = "I got cut off from the rest of the crew. We did not expect to be attacked by nerubians. Though I can't imagine the rest quitting.\n\nOur duty is too important to give up just yet. \n\nBarging right into the mine could cause the nerubians to frenzy and hurt the others. So, I found a third way to get in earlier. Though undetected will still be tough. \n\nFollow me.", completion = "You made it undetected, good. Time to surprise these Nerubians!", objectives = "Meet Alvegar at the third entrance of the Opalcreg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82797] = { id = 82797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hit Rock Bottom", description = "A long way down to be sure, but I am certain that you can make it. \n\nIf you doubt yourself, I made some parachutes to help you stick the landing. \n\nOnce you get to the bottom of the cave, look for Cenderragg. She's the most senior of the group and probably has the best idea on how to rescue the team.", completion = "Who are you and why are you here?", objectives = "Get to the bottom of the mine and find Cenderragg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82798] = { id = 82798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opal of Mine", description = "I'll be direct with you. We have a goal here and those opals are the center of it. \n\nNo one will leave until we get the job done, the opals are too important. If you could gather enough ore, we could convince them to leave.  \n\nBut be careful, those nerubians are dangerous.", progress = "Why did the nerubians have to show up? We were almost complete.", completion = "We collected much. I worry that it still won't be enough.", objectives = "Help Cenderragg collect 8 Opal Ore from the Opalcreg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82799] = { id = 82799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Web Beats Rock", description = "So, Foreman Alvegar sent you? That explains it.\n\nThe situation is not great. This place is crawling with nerubians and they're showing us no mercy. They forced us to mine and took our hard-earned opals. \n\nWhen you disobey, they web you up. \n\nI was barely able to escape them when they came. The others... Well, that's where you come in.\n\nWith you here distracting them, I can go rally the webbed earthen.", completion = "Thank the machine! They're free!", objectives = "Rescue 6 earthen workers in the Opalcreg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82800] = { id = 82800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sedimental Moment", description = "Some have started to evacuate, but there's a stubborn few that just won't let go. \n\nCould you say something? \n\nMaybe an outsider's perspective will get them moving.", progress = "Why must these few be so stubborn?", completion = "It worked! Thank you. \n\nAny earthen saved is a great moment for us all. No matter how long we have left.", objectives = "Help Cenderrag inspire the earthen workers in the Opalcreg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82801] = { id = 82801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beetlejeweled", description = "To make sure no other earthen gets harmed we're going to have to eliminate their leader. \n\nYou know the saying, rid yourself of the foreman and the whole line collapses. \n\nEither way, to get to safety we're going to have to go through them.", completion = "You made it back, I was beginning to think all hope was destroyed. \n\nAlvegar filled me in with the issue. I'm just glad all our people are safe, and we got the opal too.\n\nA small win, but a win.", objectives = "Defeat Kix'arak outside of the Opalcreg Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82809] = { id = 82809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gryphons of a Feather", description = "Hey there! I notice ye got a stormrook that's lookin' rather unhappy. Let's see what we can do to cheer 'em up.", progress = "Kwee wah?", completion = "<Squally chirps with delight, hopping around excitedly.>", objectives = "Find a way to cheer up Squally.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82810] = { id = 82810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Found", description = "Yer back!\n\nIf you're up for it, there's more things in the muck to be found. Might have to dig a bit deeper this time.", progress = "What'd you find?", completion = "Same as before, I'll have you take some of these to see if we can't find their owners.", objectives = "Find 6 lost mementos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82813] = { id = 82813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Borrowed", description = "Ah, now there's my good friend! Me and Mags are still here, looking for memories. Got a moment to spare for help?", progress = "What'd you find?", completion = "These definitely have stories to them. See if you can't find their owner again.\n\nAnd thanks. Don't know if we'll find much more.", objectives = "Find 6 lost mementos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82814] = { id = 82814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decommissioning Darkness", description = "Decommissioning a machine is a rare necessity. It must be done with care and regret.\n\nWe put much of ourselves into our work. To destroy it is to destroy a part of ourselves. In doing so, we admit our failure to protect the Titans' work.  But where stone rebels against stone, we must stand firm.\n\nImperative: Destroy it. Recover Arbauch's memory gem.", progress = "Regret. This should have been my burden.", completion = "There is no joy in the death of a machine, but I express gratitude. I suspect Arbauch would too. \n\nHis decisions were his own, but none can doubt that he devoted his life to the machines. The Titans would be proud.", objectives = "Destroy the Corrupted Golem and recover Foreman Arbauch's memory gem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82815] = { id = 82815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturdy Locket", progress = "What do you have there?", completion = "Wait... this locket." }
quests[82817] = { id = 82817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbance Detected: Blackrock Depths", description = "The Timewalkers claim that they detected a time-displaced object in Blackrock Depths.\n\nWhile that fight may have ended in our defeat, the Dark Iron clan knows what's at stake should history change. We could lose the current dwarven alliance and all the good it has brought.\n\nRecover the object and protect our current peace.", progress = "It brings me no pleasure, asking you tae fight against us. I feel for the bronze dragons and all the work they do tae protect the timeline.", completion = "Strange that I must thank you for ensuring my clan's utter defeat. But from the ashes we rose, soot and all.\n\nThank you, champion.", objectives = "Recover the Timewarped Ironforge Blueprints from Emperor Thaurissan in Blackrock Depths.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82832] = { id = 82832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wooden Figure", progress = "Got a cat problem?", completion = "Ah, this is cute. Couldn't tell you where it came from - it appears to be made by a hobbyist rather than an artisan. I'll put it up on display though." }
quests[82835] = { id = 82835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calcified Journal", progress = "Are you looking for someone?", completion = "Ah! I haven't seen this in years..." }
quests[82836] = { id = 82836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zero Out Xerosh", progress = "Were you able to defeat the siegelord?", completion = "With the nerubian leader defeated, we should be able to leave the defenses to the Arathi.\n\nYou've saved many lives today, {name}.", objectives = "Defeat Siegelord Xerosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82843] = { id = 82843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Earthy", description = "Ah, another one of you lot, eh? Well, if you want to eat, you need to help.\n\nPick me a fresh taro, will you?", progress = "Have you brought the taro?", completion = "Oh. Well... you tried.", objectives = "Harvest a nearby taro plant for the chef", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82844] = { id = 82844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Not Ruined", description = "Alright, I'll come with you. Show you how to do this properly. If I'm up, we might as well stock up on taro. Can't rely on adventurers to do delicate work, I suppose.", progress = "Is that all of them?", completion = "Much better. This will last for a while. If you want to eat, though, I'll need a little more help.", objectives = "Harvest 6 taro with the chef. Properly, this time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82845] = { id = 82845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ivory Tinderbox", progress = "What brought you to the Priory, outsider?", completion = "A lost item?\n\nThis is mine, but I hesitate to say it was lost." }
quests[82846] = { id = 82846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dented Spearhead", progress = "We meet again. How can I help you?", completion = "Ah, I thought I simply misplaced this." }
quests[82847] = { id = 82847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough Garlic", description = "Normally, this would do. I'm not so picky. But you're a guest. So we'll need some garlic.\n\nI found some growing on a hill not far off. Shouldn't be there. But it is.\n\nToo bad hydras found it, too.\n\nYou have weapons and such, right?", progress = "You think that's enough?", completion = "Ahh, there we go. That is enough garlic.", objectives = "Collect garlic for the chef.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82848] = { id = 82848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sous", description = "Alright, now help me finish this.", progress = "Time to cook!", completion = "Thanks, stranger. It's nice to have some company to pass the time. Good luck on your travels.", objectives = "Help the chef prep a meal. Stand by the chef's table and use meal prep abilities to assist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82849] = { id = 82849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filigreed Cleric", progress = "Got a request from the kitchen?", completion = "Well look here. I was wondering where this was." }
quests[82852] = { id = 82852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Assignment: Lynx Rescue", description = "WQ" }
quests[82894] = { id = 82894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Price of Hope", description = "{name}, good to see you. I am about to make a trip to the local infirmary. \n\nWould you care to join me?", progress = "We lose so many, we need to save those we can.", completion = "Thank you. If you can come back and help Kaeleb another day, it would be much appreciated.", objectives = "Meet General Steelstrike in the Mereldar Infirmary.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82895] = { id = 82895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Weight of Duty", description = "I am now the caretaker of Mourning Rise.\n\nAt last, I feel the weight of this new responsibility on my shoulders. It is a great honor, but one I must prepare myself for.\n\nPlease, help me complete one final task, and then I will be ready.\n\nMeet me back at Fallside Outpost.", progress = "One more task, and then I shall truly be the caretaker.", completion = "You brought Korgran peace in his final moments, and now you have helped me fill his absence.\n\nYour aid will not be forgotten.", objectives = "Meet Urtago at Fallside Outpost to help her take on her new role.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82916] = { id = 82916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Fungi Bloom", description = "Greetings! \n\nPerhaps you can help me with some busy work? I have so many orders that I have miscalculated several units of Mycobloom. To be honest, a bit more than several.\n\nWill you be kind and gather the rest for me?", progress = "I don't mean to rush, but I need the mycoblooms as soon as possible. Please.", completion = "Thank you {name}! These are wonderful samples.\n\nHere, take this as my appreciation for your time.", objectives = "Gather 20 Mycobloom for Akdan in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82937] = { id = 82937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
