quests[82945] = { id = 82945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[82946] = { id = 82946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rollin' Down in the Deeps", description = "Got a big task for you, yes? \n\nFetch things, all waxy. Bring 'em quick, yeah? Much to trade for good finds. \n\nGet snufflin', friend!", progress = "You done snufflin' yet? Got those waxy bits?", completion = "Ah, back so soon! Show me those waxy treasures.", objectives = "Collect 10 Odd Globs of Wax.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82952] = { id = 82952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Opportunity to Relax", description = "Hey, you! Yeah, you'll do. You wanna make some coin? We's tryin' to drum up business at our exclusive resort. Maybe ye heard of it? Opportunity Point Spa and Resort! \n\nBoss sent me up to Gundargaz to pass out this stack of flyers, but my trike blew a gasket and I'll be stuck here for a bit repairing her. How's about you head up there and pass them out for me? Look for the tired and weary types.", progress = "I shoulda listened to my mechanic. He told me there was no way my trike was gonna make it all the way up here, but my boss has been on me to get more clients. \n\nDid you pass out those flyers yet?", completion = "You're back! How did it go? Should we start preparing for large crowds?", objectives = "Pass out 6 flyers to tired workers in and around Gundargaz.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82953] = { id = 82953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cordial Invitation", description = "It is clear to me now that my time as the Vizier is drawing to a close. The nature of my service to Azj-Kahet must change. To that end, I have one final task to ask of you, {name}.\n\nYou have done a great deal of work in the City of Threads since your arrival. No doubt your reputation now precedes you. Seek out our allies within the city and ask them to congregate in the Umbral Bazaar. I have a message prepared for them all.", progress = "Move expeditiously, friend. We do not have much time.", completion = "You've gathered quite a crowd. Excellent.", objectives = "Spread word of the Vizier's announcement within the City of Threads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82954] = { id = 82954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knives in the Dark", description = "No doubt you recall the assassin that sought to end me when last we met on this spot. If it weren't for your intervention, I would not be here now. Make no mistake, if my role in all of this has been compromised, that assassin will not be the last.\n\nIf I am to make my last great stand, then I will need your help in ensuring my safety until the final hour. Scour the city for more of those skulking threats, and do what you must to ensure they will not interrupt my speech.", progress = "Take care that you are thorough, friend. I would really rather not get stabbed today.", completion = "Preemptive violence is a tad gauche, I think. But given the circumstances, I believe the response was a proportional one.", objectives = "Slay 4 Sureki Assassins in the City of Threads.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82955] = { id = 82955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vizier's Resolve", description = "The stage is set, and the players are gathered. It is time for me to step out of the shadows.\n\nThank you for standing with me thus far, {name}. Whatever comes next, I am grateful to have met you.", completion = "It is done. A chapter of my life, thusly closed.\n\nI hope that our city can face the future with a newfound resolve.", objectives = "Witness the Vizier's speech in the Umbral Bazaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82956] = { id = 82956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Opportunity Point", description = "Glad that's out of the way. Now my boss can stop breathing down my neck!\n\nI got some repairs to do on my ride, but you should go to Opportunity Point and check it out! I'll even give you a free drink voucher to our fine establishment. \n\nGo talk to Griz Finglebur and he'll get you sorted.", completion = "Welcome to Opportunity Point! You got a drink ticket, eh? Coming right up!", objectives = "Get a drink at Opportunity Point.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82957] = { id = 82957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thanks for the Wax" }
quests[82958] = { id = 82958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Blessings", description = "You there!\n\nI am running low on Blessing Blossoms, and new supplies will not be delivered to me before I run out.\n\nCan I trust you to gather these herbs for me?", progress = "Were you able to get the herbs I asked for?", completion = "Aha! I appreciate your work. It is good to see that I can trust you with these tasks.\n\nI have something small for you. It is not much, but I hope it will come in handy.", objectives = "Gather 10 Blessing Blossom for Akdan in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82959] = { id = 82959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: Lost Diary", description = "<This diary seems to belong to Aliya Hillhelm. It would be best not to read it and simply return it to her.>", completion = "Oh my, I lost that diary a while ago.\n\nI'm quite embarrassed by some of the things I wrote in there, and honestly, some of those stories aren't even true!", objectives = "Deliver the Lost Diary to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82960] = { id = 82960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: Lily's Locket", description = "<This locket must be important to someone. Maybe Aliya Hillhelm can shed some light on it.>", completion = "You found it! That's Lily's locket. She lost it around the time of Aunt Gerta's accident. \n\nWe've been searching everywhere for it.", objectives = "Deliver Lily's Locket to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82961] = { id = 82961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: The Chicken", description = "<This wayward chicken should probably be returned to Aliya Hillhelm at the Hillhelm Stead.>", completion = "Oh, Wilber, you crazy chicken! You never fail to end up in the most unexpected places!\n\nAunt Gerta used to chase Wilber all over looking for its hiding spots. I'm grateful you brought her back home.", objectives = "Deliver the chicken to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82962] = { id = 82962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Handful of Luredrops", description = "You, yes you.\n\nEver heard of the Luredrop? It is a rare carnivorous plant that eats insects. Now we do not have insects here, but I do wish I had a few samples. You let me know if you find any, or better, just bring them to me.", progress = "Remember, they are rare finds.", completion = "Would you look at that! These are wonderful samples. \n\nYou and I should open a business. I will sell and you will get the supplies.", objectives = "Gather 3 Luredrop for Akdan in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82963] = { id = 82963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: Lil Piggy", description = "<This Lil Piggy should probably be returned to Aliya Hillhelm at the Hillhelm Stead.>", completion = "This little piggy has been missing for days, and I've been holding out hope for it to find its way home.", objectives = "Deliver the Lil Piggy to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82964] = { id = 82964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: Uncle's Eye", description = "<A glass eye. It's quite a valuable item. Perhaps Aliya Hillhelm might know who has lost it.>", completion = "Is that Uncle Tomas's eye?\n\nHe has a habit of misplacing it whenever he ventures out for a stroll in the fields.", objectives = "Deliver Uncle's Eye to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82965] = { id = 82965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light and Shadow", description = "There are two herbs that I am missing. \n\nThe first is Arathor's Spear, and the second, and far more rare, would be Orbinid.\n\nNow I know what you are thinking: these are both rare. Yes, to a point, but I am not asking for many and the pay is well worth it.\n\nWhat do you think? Can I trust you for the task?", progress = "Did you get both?", completion = "I knew it!\n\nYou are one of the best herbal goods supplier I have known.\n\nHere, take this. It is the least I can do.", objectives = "Gather 5 Arathor's Spear and 5 Orbinid for Akdan in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82966] = { id = 82966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: Unusual Potato", description = "<This potato has such an unusual shape. It almost resembles a famous person. Aliya Hillhelm will definitely want to see this!>", completion = "This potato is incredible. It's almost as if we're meeting General Steelstrike in person! \n\nI will keep it on display in the house.", objectives = "Deliver the Unusual Potato to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82967] = { id = 82967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: The Ear", description = "<A most disturbing discovery, you should show this to Aliya Hillhelm at Hillhelm Stead.>", completion = "As unsettling as it may be, I'm grateful you found this. After the accident, parts of Gerta have been resurfacing all over the fields.", objectives = "Deliver the ear to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82968] = { id = 82968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillhelm Family: The Plowhead", description = "<A plowhead in pristine condition. Aliya Hillhelm at Hillhelm Stead could probably make use of this.>", completion = "Thank you sincerely. This will be incredibly useful. Many of the plowheads were damaged when the harvester went haywire.", objectives = "Deliver the Plowhead to Aliya Hillhelm at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82969] = { id = 82969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stone Tracing", description = "Couldn't help overhearing. Not to brag, but goblins are specialists in the field of rampaging robots.\n\nIf that golem's as unstable as Danagh says, it'll be leaking all sorts of energy. Take this, run a few scans, and you'll find it. Oh, and be careful. Animals tend to go a little cuckoo when you power this thing on.\n\nNo charge--a murderous golem's bad for business. And I kinda feel bad making you work just to find a dead guy.", completion = "Curious. It seemed to be wandering along the river. Unimportant, we have its location. We will find it and decommission it.", objectives = "Scan remnants of the golem to triangulate its location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82970] = { id = 82970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bloom and a Blossom", description = "Hi, you there!\n\nI have a task for you.\n\nI require a handful of Mycobloom and some Blessing Blossoms. There is a nice payment for them if you are up for the task.", progress = "I have your reward waiting for you if you got me the herbs.", completion = "Mountain bless me!\n\nIt is good doing business with you.", objectives = "Gather 10 Mycobloom and 10 Blessing Bloom for Akdan in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82971] = { id = 82971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queue Bonus" }
