quests[82980] = { id = 82980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queue Bonus" }
quests[82990] = { id = 82990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undoing the Damage", description = "Apologies. Arbauch was not here for repairs--he stole that golem.\n\nArbauch and I worked alongside it for years in the darkest reaches of the Deeps. The work took its toll on the golem. It became erratic, dangerous even. We planned to decommission it, but when the time came, Arbauch couldn't bear it. He'd become attached. Before it could be destroyed, he took it and fled.\n\nIt must be found, but the damage to this substation is catastrophic. With your help, I will attempt repairs.", completion = "A foreman and a substation lost. Blast. I was careless.", objectives = "Defend Danagh while he repairs the substation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82992] = { id = 82992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormcharged Goods", description = "Greetings my friend!\n\nI am looking for someone who is willing to run a quick errand. I am running out of goods and I have not heard from my leather supplier for quiet some time. If I can not supply skins and leathers, the leatherworker will not be able to produce apparels.\n\nI will reward you if you can bring me several Stormcharged leathers.", progress = "Any good news? I still have not heard from my leather supplier.", completion = "You have the leathers? Titans be praised!", objectives = "Gather 20 Stormcharged Leathers and deliver them to Ginnad in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82993] = { id = 82993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Shadows", description = "Hello there!\n\nI have heard of fantastic materials that can be thread and put together from some... peculiar materials.\n\nIf you are the type who enjoys travelling through the last sunny parts of Khaz-Algar, will you be kind enough to gather Kaheti Swarm Chitin and Sunless Carapace for me? I will reward you nicely if you can supply me with some samples.", progress = "I feel a certain eagerness to get my hands on these materials.", completion = "How peculiar. There is no saying what can be achieved with these materials. Only time would tell, titans willing.", objectives = "Gather 5 Kaheti Swarm Chitin and 5 Sunless Carapace, and deliver them to Ginnad in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[82994] = { id = 82994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wax Contribution" }
quests[82995] = { id = 82995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerubian Device", description = "A strange device of Nerubian origins. Aevery Flamestonge at Hillhelm Stead might be intrigued by this.", completion = "This is incredibly intriguing. \n\nIt's possible that the Nerubians utilize this device to manipulate spiders and other creatures to harass our farms.", objectives = "Deliver the Nerubian Device to Aevery Flamestonge at Hillhelm Stead.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83021] = { id = 83021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - TWW - Normal Random - 1st" }
quests[83022] = { id = 83022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - TWW - Normal Random - Nth" }
quests[83023] = { id = 83023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[83024] = { id = 83024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stormrider's Bond", description = "So, you think yourself worthy of a Stormrider's armor?\n\nWe Stormriders were titan-made to fight and to ride stormrooks. Even so, we must prove our competence in battle before we gain clearance to wear Stormrider armor. I see no reason why you should not undergo the same challenges.\n\nGo. Show me you have the power of the storm within you.", progress = "Come back only when you've proven yourself worthy.", completion = "Hm. Clearance granted.\n\nThis armor is generally reserved for Stormriders. But for your valor, I give you special clearance. Wear it with pride.", objectives = "Collect 50 Storm Spirits by slaying powerful creatures of Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83025] = { id = 83025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sacred Connection", description = "I may have granted you clearance to wear our armor, but to focus the storm's power through it as the greatest Stormriders do...\n\nThe greatest Stormriders in our order do not merely possess the power of the storm. They have mastered it. And this mastery is forged over many battles.\n\nIt is time to prove yourself as one of our best.", progress = "Your reward shall be properly equal to your efforts.", completion = "Yes. This is the mastery seen in the greatest Stormriders. Let this armor be proof of that.\n\nWear your armor with pride. It is not an honor to be taken lightly.", objectives = "Collect 500 Storm Spirits by slaying powerful creatures of Khaz Algar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83026] = { id = 83026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - TWW - Heroic Random - Nth" }
