quests[83028] = { id = 83028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Snufflers" }
quests[83031] = { id = 83031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hardest Part", description = "<Aethas sighs heavily, his voice tinged with sorrow.>\n\nDalaran... once a symbol of unity and arcane mastery, now reduced to rubble and ash. Again.\n\nSo much loss and so much pain. Friends and comrades gone in an instant, their voices silenced by Xal'atath. \n\n<He takes a deep breath, steeling himself against the overwhelming grief.>\n\nBut now is the time for action--not grief. We must regroup with the remaining Kirin Tor.\n\nHowever, the right words do not come easily.", progress = "What does one say in times like these?", completion = "We have taken the first step at least.\n\nNow, we wait.", objectives = "Help Aethas Sunreaver send a message to the surviving mages of Kirin Tor in the Tranquil Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83043] = { id = 83043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Crests", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83046] = { id = 83046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved Crests", objectives = "Expressing gratitude. Please accept this as a reward for all your hard work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
