quests[83080] = { id = 83080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taelloch Cleanup" }
quests[83081] = { id = 83081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Enough Minerals", description = "I did nae think the Opalcreg would be under attack! I'm sure Brinthe did nae either.\n\nPeacekeeper Hektare will nae let me fight, but maybe she will let you.\n\nI'll stay here an' tend to this earthen. I know a trick or two after bein' in Dornogal.\n\nOh, but... Brinthe really needed those opals...", progress = "I'm sure I can make a poultice for this earthen. Oh, 'tis a shame I cannae get any opals.", completion = "Fire Opals? You found some?\n\nBrinthe'll be so pleased!\n\nThis earthen seems to be feeling better as well. A win-win all around!", objectives = "Collect 6 Earthen Fire Opals from the Opalcreg in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83082] = { id = 83082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Opalfront", description = "I'm a city guard, not a soldier! But these people need our help!\n\nThere are too many nerubians for us to clear out. We can only keep this chokepoint and hope the miners make their way to us.\n\nThat one was too small. But you look like a fighter. Help us!", progress = "We will do what we can to help the miners escape.", completion = "Thank you, outlander. You have given them a fighting chance.", objectives = "Kill nerubian forces at the Opalcreg in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83083] = { id = 83083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Place Forgotten", description = "There is... a place behind Dornogal that I cannot go.\n\nAnd I am not the only one. Something--a force, most likely titan in origin--keeps the earthen from investigating a small portion of the island behind the city.\n\nThis, of course, fires my curiosity. But for thousands of years I have dutifully kept away. It seemed the titans' will.\n\nThe site emits a faint signal like the one from this device. Perhaps it is \"the key\" in a literal sense to what lies there.\n\nWe will see.", completion = "I cannot describe what this place feels like to me.\n\nIt is... oppressive. I cannot think.\n\nThe urge to turn back is... strong.", objectives = "Meet with Speaker Brinthe and Dagran behind Dornogal in the Isle of Dorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83084] = { id = 83084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Orders", description = "Long ago, there were once plans to build a tunnel through the mountain into Dornogal. \n\nBefore excavation could begin, the surrounding area was suddenly abandoned. \n\nThere is no record of what happened. Only a... deterrence--the field--that keeps earthen away from this region.\n\nEvery part of my cognitive matrix is pressing for me to leave. But we must persist. \n\nThe device's signal indicates something lies within the nearby tower.", progress = "I'm not sure what's afflicting Brinthe, but it's clear she's in pain. I offered to escort her back to the city but she refused.\n\nI will stay with her an' make sure she does nae take a turn for the worse and try an' figure this device out more too.", completion = "Forget what ye found in the tower--did ye see that?! Those looked like titan watchers!\n\nBut... what does it all mean? And who were they?", objectives = "Investigate the abandoned tower behind Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83087] = { id = 83087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Guard", description = "Dornic... Galan... I've heard those names at the Proscenium!\n\nBut who was speakin'? They were nae happy with Galan. All those earthen bodies...\n\nRepurposed... like reprogrammed? Tae protect what?\n \nLet's chase the other signal. Looks like it leads up ahead intae the hills.\n\nI'm goin' to stay here with Brinthe an' investigate this tower further. You take the device.", progress = "I'll stay here with Brinthe. I dunnae want anythin' to happen tae her.", completion = "You saw another memory? And it attacked ye?\n\nThat's awe--I mean, I'm so glad ye are okay.\n\nWhile ye were tracin' the signal, I found more notes. I put 'em together for ye to read. It's more about Dornic and Galan.\n\nBut it looks like we know where Galan ended up at least without 'em--buried under tons o' rock. But what was she guardin'?\n\nWhat was so important that she was repurposed tae safeguard it for thousands of years?\n\nArgh! We have more questions than answers. I dunnae like it.", objectives = "Follow the signal and witness a second memory", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83088] = { id = 83088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caustic Collectables", description = "Boxenkle is my boss--and my mentor. Best slimediver there ever was! Until now...\n\nIt's not him--slimediving isn't what it used to be! The slimes have gotten more toxic over time. \n\nI think it's gotten so bad that we all should be wearin' eye protection--not just me. But ol' Enkle's a traditionalist. It'll take more than a few red eyes to convince him.\n\nThat's where you come in. If you can get residue samples from the really nasty slimes, maybe I can make a compelling case for ol' Enkle!", progress = "Have you found enough residue from the oozing salvage?\n\nMake sure to get the really nasty stuff. You know, the stuff that sticks to you but also melts your skin?", completion = "That's it! That's the stuff!\n\nMaybe Enkle will listen to me this time...", objectives = "Collect 6 Stinging Residue from Acidic Salvage in The Vatworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83089] = { id = 83089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giving Goblins Goggles", description = "My mentor Enkle may be the loudest voice around here, but he's not the only one who needs help.\n\nOur whole crew only listens to him! Which means no one's wearing proper protective equipment.\n\nTake these goggles and convince everyone to take 'em on a trial run. Maybe if they all start changing their minds, Enkle will listen.", progress = "Everyone's working along this river here. You can't miss them!\n\nUnless they haven't found the river. But that only happens half the time, so I'm sure it's fine.", completion = "<Kazzandra cheers.>\n\nFinally! Everyone's here, and they're all wearing goggles. Enkle had better listen to me this time!", objectives = "Talk to 5 Slimedivers in The Vatworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83091] = { id = 83091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shield Your Eyes", description = "Causticaria? Is he crazy? No one has ever been able to process that monster!\n\nWe have to stop Enkle before he gets himself hurt!\n\nCausticaria lurks down this canal. Grab your goggles and follow me!", progress = "Has Causticaria gotten even bigger? The stench is burning my nose hairs from here!", completion = "He's okay! Thank you so much for your help, {name}!", objectives = "Defeat Causticaria in The Vatworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83092] = { id = 83092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Igneous End", description = "When the magma transport pipe failed, our workers rushed down to begin repairs.\n\nThe elementals caught us unawares, rising up and attacking with great gouts of lava.\n\nFortunately, we earthen are made of stern stuff and a little magma is hardly going to be the end of us. Unfortunately, the cooling magma has hardened into stone shells, entombing our repair crews where they stood.\n\nSmash their stony prisons and free my workers!", progress = "Don't worry about hurting them, just get them free.", completion = "Thank you, topsider. With our crews returned, we can get back to work.", objectives = "Free Entombed Earthen from their stone shells near Hallowfall Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83096] = { id = 83096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Undermine", description = "There ya are! I'm Grimla. Welcome to Undermine. If you wanna get up to speed with the current situation, you've come to the right goblin. Pamsy vouched for you, that's good enough for me.\n\nI've got a coupon you can use at the Incontinental Hotel. We'll start there.\n\nLet's take a ride in \"Gramps,\" my hot rod! Hop in when you're ready.", progress = "Did you hear anything good while you were gettin' yourself settled?", completion = "So, that's the Incontinental Hotel. Things go downhill from here.", objectives = "Go to the Incontinental Hotel with Grimla and learn more about Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83097] = { id = 83097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cinder and Storm", description = "The wild creatures here have stunning properties. I wonder what might happen if I combine them?\n\nBe on the lookout for Bottled Storm and Burning Cinderbee Setae. I'll reward you generously if you can bring me some samples. Oh, and if you gather them yourself, mind that you don't get burned. Or zapped. Or both.", progress = "Who knows what could happen if we combine these materials!", completion = "Wonderful! I can't wait to get to work.", objectives = "Gather 5 Bottled Storm and 5 Burning Cinderbee Setae, and deliver them to Ginnad in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83098] = { id = 83098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snap and Crackle", description = "Do you have a moment?\n\nI'm looking for some materials with an edge. Something sharp and with a bit of sizzle. If you can find me Honed Bone Shards and Thunderous Hide, I'd be more than happy to compensate you.", progress = "Together, these materials will make a real statement.", completion = "Just what I was looking for! Can't wait to put them to use.", objectives = "Gather 5 Honed Bone Shards and 2 Thunderous Hide, and deliver them to Ginnad in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83099] = { id = 83099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mergers and Acquisitions", description = "When the nerubians launched their attack on my meadery, they left it a burnt-out husk. Adelgonn promised to rebuild it, but I got impatient and accepted the Venture Co.'s offer to help with its \"restructuring.\" \n\nBut now, it's clear they had their own agenda. Blasted goblins have taken over, and they're driving the place into the ground. They've ramped up production to unsafe levels, pushing the cinderbees and our equipment to their limits.\n\nPlease help fix this, {name}.", progress = "Thinking about those goblins in my meadery... Oh, it makes my head feel molten. And that makes me think of my cinderbrew!", completion = "A heartfelt thank you for what you did at the Cinderbrew Meadery. \n\nDriving away Venture Co. was no small feat, but thanks to you, we've reclaimed our beloved meadery and will resume making cinderbrew the right way--the way we've made it for centuries.", objectives = "Defeat Goldie Baronbottom and help Wenbrandt reclaim the Cinderbrew Meadery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83100] = { id = 83100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking the Shell", description = "Welcome!\n\nYou wouldn't believe the amount of materials we go through up here, and not just the rare stuff! We could always do with more Gloom Chitin. If you find some, bring it to me. I'll see to it you get paid.", progress = "Manage to lay your hands on some yet?", completion = "Perfect timing, we were just about to run low.", objectives = "Gather 20 Gloom Chitin and deliver it to Ginnad in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83101] = { id = 83101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reaching for Resources" }
quests[83102] = { id = 83102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bismuth is Business", description = "Do you know the backbone of a good mining operation? It's not the rare, flashy ores. It's good, common Bismuth.\n\nAnd we don't have nearly enough! Wherever you go, keep an eye out for Bismuth. Bring me as much as you can. \n\nCompensation is assured.", progress = "Bismuth is business, and business is booming!", completion = "You're back? Gratitude. You clearly know how to use a pick.", objectives = "Gather 20 Bismuth and deliver it to Tarib in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83103] = { id = 83103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acquiring Aqirite", description = "You there!\n\nHave you heard of Aqirite? Valuable, versatile, very often surrounded by nerubians.\n\nI need that ore, and I don't care how you get it. If a nerubian does try to stop you, give them a whack for me.", progress = "Well, have you got it yet?", completion = "Aqirite is always appreciated. I'll get it to where it needs to be.", objectives = "Gather 10 Aqirite and deliver it to Tarib in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83104] = { id = 83104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identifying Ironclaw", description = "I sent a team to mine some Ironclaw Ore, they said they didn't see any. Can you believe that? It's a blasted great claw coming out of the ground!\n\nI'm not sending them again. I trust you'll know Ironclaw Ore when you see it. Bring it to me, and you'll be rewarded.", progress = "Trust me, you can't miss it.", completion = "Appreciation expressed. I knew I could count on you.", objectives = "Gather 10 Ironclaw Ore and deliver it to Tarib in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83105] = { id = 83105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rush-order Requisition", description = "Good to see you, I've got work.\n\nThe blacksmiths just sent a last-minute requisition for rare ores. Gravel-munching hammer-heavers, would it kill them to plan ahead? Well, I'm sure you can handle it.\n\nLooks like you'll need to track down Aqirite and Ironclaw Ore.", progress = "Do you have them? The smiths have been chewing my ear off.", completion = "Excellent work. These ores will be greatly appreciated.", objectives = "Gather 5 Aqirite and 5 Ironclaw Ore, and deliver them to Tarib in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83106] = { id = 83106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Null Pebble Excavation", description = "Ever seen a Null Stone? Well, you will. They're rare, but we know how to put them to good use. Don't worry, I only need a couple.\n\nWhile you're at it, pick up any Bismuth you find. You can never have enough Bismuth.", progress = "Any luck with those Null Stones?", completion = "Marvelous! Hope you didn't go to too much trouble finding these.", objectives = "Gather 10 Bismuth and 2 Null Stone, and deliver them to Tarib in Dornogal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83108] = { id = 83108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daily Diagnostics", description = "It is my duty and honor to take diagnostic readings every day. I determine the output and efficiency of the Stonevault's great machines. The burden is mine.\n\nDescribing complication: now that skardyn have overrun the Stonevault, I cannot reach my machines!\n\nSolution proposed: I have heard that you are a hero of great renown. Please go in and gather today's readings for me. Timing will be critical in the event anything goes wrong. Awaiting confirmation.", progress = "There are numerous consoles that assist with the running of the great machines within the Stonevault. Work does not cease, even in the face of this madness.\n\nPlease, get me those readings as soon as you can!", completion = "Thank you for getting me those readings. Hopefully the analysis will show that everything is in order with the great machines. \n\nUntil it has been deemed safe for us to return to the Stonevault I'm stuck here cooling my gears. But at least I know what today's readings are like.", objectives = "Take diagnostic readings of 4 machines within the Stonevault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83109] = { id = 83109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Grimla Express", description = "Next stop, Tailgate Park. Bilgewater Cartel used to be in charge there, but Gallywix had other plans. Now the Darkfuse act like they own the place and the Bilgewater... Well, they do the best they can. \n\nI'm not sure who runs it now, if anyone does.", completion = "They look up to Gazlowe. Maybe you folks showing up will give 'em a little hope.", objectives = "Head to Tailgate Park in Grimla's hot rod.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83110] = { id = 83110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deliver Equipment", description = "Deliver safety equipment to Steamwheedle goblins to allow them to perform black blood experiments more safely." }
quests[83113] = { id = 83113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recover Tools", description = "Kill black blood slimes and recover tools absorbed by the slimes." }
quests[83114] = { id = 83114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Red Tape", description = "First it was just Black Blood, now ethereals?\n\nI don't know how all this squares, but we need help if we wanna find out.\n\nOrweyna left to get Alleria a while ago. We should head over to Slam Central Station to see if they've made it down here yet.", progress = "We shoulda known. These guys see an outsider unescorted and try to pull a fast one.\n\nSee if you can change their minds.", completion = "Now that Alleria's here, let's get to the bottom of this business--startin' with Noggenfogger.", objectives = "Find Alleria at Slam Central Station.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83115] = { id = 83115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Mix", description = "I don't like thinkin' that Noggenfogger's part of this, but the only way we'll know is if we go and talk to him.\n\nSteamwheedle's headquarters is probably a good place to start lookin' for him.\n\nWe'll give him a chance to explain himself. If it's a misunderstanding, or he's just gotten himself into trouble, I need to know.", progress = "You see how many Darkfuse they've got here?", completion = "<Gazlowe lowers his voice.>\n\nThey've got this place crawlin' with Darkfuse. Noggenfogger's bein' watched. Closely.", objectives = "Speak to Marin Noggenfogger at the Vatworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83116] = { id = 83116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potion Commotion", description = "It really is great to see you and Gazlowe! I was just thinkin' about how much I wanted to see you both on my birthday.\n\nA day when I'm under no forms of duress or coercion whatsoever! N-None at all.\n\n<Cautiously, he glances at the Darkfuse guards, then whispers to you.>\n\nI'll tell you whatever I can if you get rid of them.\n\n<He nods subtly towards his alchemy station.>", progress = "I'll keep an eye on Noggenfogger. You get it done.", completion = "Venture and kaja'mite. Two more puzzle pieces.\n\nLet's hope they all fit together eventually.", objectives = "Collect some Semi-Deluxe Noggenfogger Elixirs, then use them to distract 8 Stationed Labguards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83117] = { id = 83117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing a Lead", description = "Venture doesn't exactly have a history of being an upstanding cartel. Their loyalties can be bought cheap, and they don't got qualms about means justifyin' ends.\n\nWe knew they was working with Gallywix, we just didn't know how deep they were in with him.\n\nLet's go check out those kaja'mite supply lines. No time to lose.", completion = "Lots of Darkfuse, but less than they had back at Steamwheedle. Probably 'cause Venture's more compliant.", objectives = "Meet Gazlowe outside the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83118] = { id = 83118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check the Schedule", description = "If there's one thing Venture does keep in order, it's their paperwork. They're real particular with dividing their workforce and keepin' everything on schedule. They're efficient, I'll give 'em that.\n\nUp ahead is one of their scrapyards. They should have schedules posted around the place for Venture employees to record their hours worked and see what they got comin' up.\n\nGrab as many as you can find. We'll check out Venture's headquarters in the meantime.", progress = "They should have schedules posted all over the place. Hopefully this isn't a wild flamingo chase.", completion = "<Gazlowe reads over the schedules quickly, his expression souring.>\n\nWell, good news is Noggenfogger wasn't lyin'.\n\nBad news is... this is a LOT of names. All gettin' sent to the Kaja'Coast in Zuldazar.", objectives = "Gather 3 Employee Schedules.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83119] = { id = 83119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Worth a Shot", description = "Venture Co. has a pretty bad track record, but not everyone workin' for the cartel is bad news. Some of us are tryin' to make ends meet.\n\nMaybe we can talk sense into some of 'em. Less Venture workers means less people doin' Gallywix's dirty work.\n\nVenture Co. employs a lot of non-goblins, so no one will question you bein' around as long as you've got a uniform on. I've got a spare that will probably, mostly, sorta fit you.\n\nSee if you can get 'em to quit. If they start a fight, do what you gotta do.", completion = "That'll do.\n\nEven one fewer goblin workin' for Gallywix is a win in my book.", objectives = "Attempt to convince 10 Underpaid Workers to quit Venture Co.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83120] = { id = 83120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing the Keys", description = "If you gotta get to a confidential work site like the Kaja'Coast, you gotta check out a punch card from Krome's office up here.\n\nLead Foreman Krome is one of the big bosses who organizes how Venture's workforce gets split up. \n\nShould be easy enough for Renzik to slip in and grab the punch card, but you'll need to take care of Krome and his guard hyena. If we're gettin' to the Kaja'Coast, let's do it without becomin' chew toys first, yeah?", progress = "You clear the way for Renzik to get the punch card yet?", completion = "<Gazlowe grimaces as he inspects the foreman's weapon.>\n\nThe battery in this thing is powered by Black Blood.\n\nI don't know how they managed to do that without the thing exploding, or worse. But this situation just got a whole lot more dangerous.", objectives = "Slay Lead Foreman Krome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83121] = { id = 83121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asset Management", description = "I took a quick look inside that mine up ahead while you were gone. Looks like they've got Venture Co. mining out all the kaja'mite and bringin' it down to the beach. It's gettin' packaged up down there, but I couldn't tell where it was goin' afterward.\n\nWe need to cut off the supply at the origin. Deal with the supervisors in the mine, and I'm willin' to bet their workers will have enough sense to run afterward.", progress = "It won't stop the kaja'mite supply for good, but at least it'll slow them down.", completion = "Good. The fewer Venture Co. around who are loyal to Gallywix, the better.", objectives = "Slay 6 Venture Supervisors in the Lucky Break Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83122] = { id = 83122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crashing the Market", description = "When I left the Bilgewater Cartel in charge of the kaja'mite mining in Zuldazar, it was clean and safe. Well, cleaner and safer. We made a lot of deals with the Zandalari to secure that. So not only is Gallywix steppin' on our territory, but he's threatenin' the respect and trust we earned by letting Venture make a mess of this operation.\n\nBlow up the kaja'mite stockpiles you find in that mine. I don't want any dishonest kaja'mite goin' anywhere, no matter who's buyin' or sellin'.", progress = "We need to keep that kaja'mite out of circulation.", completion = "When all this is done, Bilgewater will come back here, clean this up, and do it right.", objectives = "Destroy 5 Kaja'mite Stockpiles in the Lucky Break Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83123] = { id = 83123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Miner Mistake", description = "<On the corpse of the Venture Co. employee, you find a crumpled piece of paper stuffed into an envelope. It appears to be a paystub from a kaja'mite depot in the Venture Co. area of Undermine.\n\nBelow the full address of the employer, there is a header stamped in red ink.>\n\nGALLYWIX'S SECRET KAJA'MITE WAREHOUSE - INTERNAL ONLY DO NOT ACTUALLY PRINT THAT\n\n<A note from Gallywix is poorly taped to the back of the paystub.>", progress = "What do you got there?", completion = "Well, that answers that.\n\nVenture Co. is gettin' paid by one of Gallywix's secret warehouses back in Undermine.\n\nThat means he's hoardin' all of this kaja'mite back there. What could he possibly need that much for?", objectives = "Read the Crumpled Paystub, then bring it back to Gazlowe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83124] = { id = 83124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "B.I.R.D. Watching", description = "I took those parts you collected and hotwired the components into some new machinery, then stuffed it back into the bot. Now it can be piloted usin' this remote control. The remote also lets us see and hear anything the bot does.\n\nI don't think we're gonna learn what we need to just by killin'. We're gonna need to beat Gallywix at his own game and spy on his workers.\n\nYou wanna do us the honors, {name}? I'll talk you through it.", progress = "They'll never suspect nothin'.", completion = "There's the last puzzle piece. Gallywix used Black Blood and kaja'mite to make those weapons, and now he's usin' it to repair the Dark Heart.", objectives = "Control the Hotwired B.I.R.D. to spy on Darkfuse activities on the Kaja'Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83125] = { id = 83125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Price Hike", description = "So Noggenfogger wasn't lyin'. Darkfuse strongarmed Steamwheedle into figurin' out how to make kaja'mite contain Black Blood. Looks like that's how they've been gettin' it into weapons without blowin' themselves up--or worse.\n\nThese stakes are higher than I thought, and I get the feeling this goes even deeper. I need to get Noggenfogger somewhere safe. You and Renzik take out that overseer, then meet us back at Steamwheedle.", completion = "Damn it--Noggenfogger's hurt real bad.\n\nFirst Darkfuse, now ethereals. What could they possibly want with Steamwheedle?", objectives = "Slay Overseer Dritz, then meet up with Gazlowe in Undermine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83126] = { id = 83126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethereal Invasion", description = "Just moments ago, these ethereals appeared out of nowhere. They attacked Noggenfogger and attempted to haul him off. I made short work of the first attackers, but they keep coming.\n\nNow they're searching every building and killing anyone who stands in their way.\n\nI don't know what they're looking for, but we can't allow them to continue this slaughter.\n\nLet's teach them a lesson.", progress = "We cannot let this chaos continue.", completion = "The ethereals were not expecting to meet resistance here. They were wrong.", objectives = "Kill 12 ethereals in the Vatworks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83127] = { id = 83127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Racing the Clock", description = "We were out of time before, but now we're REALLY out of time.\n\nThe ethereals are gonna beat us to the warehouse, but we might still be able to beat them to the Dark Heart.\n\nC'mon!", completion = "At least the ethereals took care of most of the Darkfuse. That's... good, probably.", objectives = "Meet Gazlowe outside Gallywix's secret warehouse in the Heaps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83128] = { id = 83128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Our People Out", description = "While Alleria looks for the Dark Heart, we need to look for the hostages. Here's hoping they're still safe.\n\nThey left some ambushers behind, but we got the best of SI:7 on our side. You think you see one of them hidin', point them out to Renzik. He'll toss a smoke bomb. That'll flush 'em out and stun 'em, so we can turn the tables.", completion = "The hostages are safe. Gallywix doesn't have leverage on any of the cartels anymore.\n\nTime to finish this.", objectives = "Save any hostages Gallywix is keeping in the warehouse and slay 10 Ethereal Heartseekers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83129] = { id = 83129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nowhere Left to Hide", description = "This barricade looks intentional. Hobart said Gallywix went off to a cave, and I'd say this sure looks like one.\n\nGallywix has to have the Dark Heart in there. Help me blast this barricade open and get ready to fight.", completion = "<Gazlowe exhales heavily, glowering back at the smoking teleporter.>\n\nThis is over. Let's leave.", objectives = "Destroy the Makeshift Barricade, then follow Gazlowe into the Hoardroom to confront Gallywix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83130] = { id = 83130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sour Victory", description = "That's it. It's over. We're done.\n\nGallywix lost, but the ethereals got the Dark Heart.\n\nAlleria needs to track them down. We need to check on everyone back at Bilgewater Flats, and then we need to go. There's nothin' else in this town for us.", completion = "<Gazlowe keeps his arms crossed, staring at some spot of nothing in the distance.>", objectives = "Meet Gazlowe at the Scrapshop in Bilgewater Flats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83137] = { id = 83137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Opportunity Explodes", description = "There ya are, {name}! Have you heard the latest news? There's a big hole blown in the side of the mountain out by Opportunity Point in the Ringing Deeps.\n\nThere were opportunistic folks taking it over, and now there's even more. We'd better hurry over there.", completion = "It's... a tollbooth?\n\nYou've gotta be kiddin' me.\n\n<Monte Gazlowe rolls his eyes and laughs softly.>\n\nI guess you can make money off of anythin'!", objectives = "Investigate the blasted hole in Opportunity Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83138] = { id = 83138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End of the Day", description = "Sprinkle and Seahorn are fine. Marin and Hobart are recoverin'. We didn't stop Gallywix, but at least the Dark Heart is... well, it's not in his hands.\n\nWhich means we can leave. Nothin' left for us to do here.\n\nFinish up whatever business you've got in Undermine. I need to get out of this damn place.", completion = "<Gazlowe wipes something ashen from his cheek, hand trembling as he stares down at it.>", objectives = "Speak to Renzik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83139] = { id = 83139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mixed Messages", description = "Lots of these workers are headed to a Venture camp just down the road. That's a great first stop for information. We'll pay the tollbooth fee. It's best to just play along for now.", progress = "See what these goblins know about the area!", completion = "Maybe whoever wanted that wall blown up also wants our attention here. We gotta dig deeper.", objectives = "Pay the toll at the tollbooth, then gather information from the northern goblin camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83140] = { id = 83140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hostile Work Environment", description = "Bigger and more dangerous than Opportunity Point? These south mines sound real bad, even if ya have a high tolerance for bad working conditions. But what are they mining? Something here is worth big money. We'll need to check it out.\n\nI'll head past the big Darkfuse camp with Renzik, stealth mode. Make a big distraction for us, will ya? I'm sure you can slow down production while you're over there.", progress = "Give us some time!", completion = "All eyeballs were on you, that was great. And you brought us a new resource, this Zirdo fella? Good thinking.", objectives = "Kill Darkfuse to keep the heat off Gazlowe and Renzik.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83141] = { id = 83141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miner Investigations", description = "What \"riches\" are they mining out of the earth? Could this deep digging be related to my visions? Surely these goblins would not find value in something like Black Blood.\n\nWe must get a closer look. Together we will gain insight into their operation.", completion = "My visions suggest there is more to the south. We should move on soon. \n\nDoes this goblin you discovered have more information?", objectives = "Examine suspicious canisters and crates with Orwenya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83142] = { id = 83142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Order of Magnitude", description = "<This document requires anyone with information about who opened the western wall to bring the information to their supervisor. \n\nIt details the reward: a promotion to working inside Undermine. It also includes a promise of the favor and \"appreciation\" of Gallywix.\n\nGazlowe will want to know about this.>", progress = "What'd you find?", completion = "Gallywix is controllin' the Darkfuse directly, and wants to know who worked against him. We could have an ally out here. That's a big clue, {name}.", objectives = "Give the Bounty from Gallywix to Gazlowe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[83143] = { id = 83143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Honest Work", description = "You're new here, right? I can tell by your questions. But don't worry, Zirdo's your best pal!\n\nI'll give you a personalized tour. Gutterville, the Venture Company town, is just south down the road. It'll be informative and interactive. You can't ask for a better experience, trust me!", progress = "I lack words.", completion = "I lack words.", objectives = "Follow Zirdo on his \"tour.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
